"""Find Minimum in Rotated Sorted Array — compare against the right end.

If nums[mid] > nums[hi] the pivot is strictly to the right of mid.

Time: O(log n)   Space: O(1)
"""
from typing import List


class Solution:
    def findMin(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:
                lo = mid + 1
            else:
                hi = mid
        return nums[lo]
